#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

pthread_spinlock_t spinlock;
int shared_resource = 0;

void *worker_thread(void *arg) {
    int ret;

    // Attempt to acquire the lock
    ret = pthread_spin_lock(&spinlock);
    if (ret != 0) {
        fprintf(stderr, "Thread failed to lock: %d\n", ret);
        return NULL;
    }

    // Critical Section: Increment shared data
    shared_resource++;
    printf("Thread %lu updated resource to %d.\n", (unsigned long)pthread_self(), shared_resource);

    // Release the lock
    ret = pthread_spin_unlock(&spinlock);
    if (ret != 0) {
        fprintf(stderr, "Thread failed to unlock: %d\n", ret);
    }

    return NULL;
}

int main() {
    pthread_t thread;
    int ret;

    // 1. Initialize the spin lock for use within the current process
    ret = pthread_spin_init(&spinlock, PTHREAD_PROCESS_PRIVATE);
    if (ret != 0) {
        fprintf(stderr, "Error initializing spin lock: %d\n", ret);
        return 1;
    }

    // Create a thread that uses the spin lock
    if (pthread_create(&thread, NULL, worker_thread, NULL) != 0) {
        perror("pthread_create");
        pthread_spin_destroy(&spinlock); // Cleanup before exit
        return 1;
    }

    pthread_join(thread, NULL);

    // 2. Destroy the spin lock, freeing resources
    ret = pthread_spin_destroy(&spinlock);
    if (ret != 0) {
        fprintf(stderr, "Error destroying spin lock: %d\n", ret);
        return 1;
    }

    printf("Main thread finished. Spin lock successfully destroyed.\n");
    return 0;
}
